import random
def partition(a, lo, hi):
    p = random.randrange(lo, hi + 1)
    a[p], a[hi] = a[hi], a[p]                 # randomized pivot
    pivot, i = a[hi], lo
    for j in range(lo, hi):
        if a[j] < pivot:
            a[i], a[j] = a[j], a[i]; i += 1   # grow smaller zone
    a[i], a[hi] = a[hi], a[i]
    return i

def quicksort(a, lo=0, hi=null):
    if hi is null: hi = len(a) - 1
    if lo < hi:
        p = partition(a, lo, hi)
        quicksort(a, lo, p - 1); quicksort(a, p + 1, hi)

