def counting_sort(a, max_val):
    cnt = [0] * (max_val + 1)
    for x in a: cnt[x] += 1
    idx = 0
    for v in range(max_val + 1):
        for _ in range(cnt[v]):
            a[idx] = v; idx += 1             # rewrite in value order
